{"content":"// TypeScript Logic & Interface Test
// Defines a Product interface and demonstrates array manipulation

// Define the Product interface
interface Product {
  name: string;
  price: number;
  category: string;
}

// Initialize an array of 5 products
const products: Product[] = [
  { name: "Laptop", price: 999.99, category: "Electronics" },
  { name: "Headphones", price: 49.99, category: "Electronics" },
  { name: "Coffee Maker", price: 79.99, category: "Appliances" },
  { name: "Desk Lamp", price: 24.99, category: "Home" },
  { name: "Wireless Mouse", price: 34.99, category: "Electronics" },
];

// Filter function for items under $50
function filterUnderPrice(products: Product[], price: number): Product[] {
  return products.filter(product => product.price < price);
}

// Execute and log results
const filteredProducts = filterUnderPrice(products, 50);

console.log("=== TypeScript Logic & Interface Test ===");
console.log("\nOriginal Products:");
products.forEach(product => {
  console.log(`  - ${product.name}: $${product.price.toFixed(2)} (${product.category})`);
});

console.log("\nFiltered Products (Price < $50):");
filteredProducts.forEach(product => {
  console.log(`  - ${product.name}: $${product.price.toFixed(2)} (${product.category})`);
});

console.log("\n=== Test Complete ===");
","path":"ts-logic-test/app.ts"}

